// Recibe output del AI Agent (campo .output) o del HTTP Ollama (campo .response)
const raw = ($input.item.json.output || $input.item.json.response || '{}')
  .replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

let res = {};
try {
  const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
  res = JSON.parse(s !== -1 && e > s ? raw.substring(s, e+1) : raw);
} catch(e) { res = {}; }

const keywords    = Array.isArray(res.keywords) ? res.keywords : [res.keywords || 'PC sobremesa'].filter(Boolean);
const presupuesto = Number(res.presupuesto) || 1000;
// pMin = 65% del presupuesto → filtra productos demasiado baratos
const pMin        = Number(res.pMin) || Math.round(presupuesto * 0.65);
const tipo        = res.tipo || 'Sobremesa';
const must        = Array.isArray(res.must)   ? res.must   : [];
const nice        = Array.isArray(res.nice)   ? res.nice   : [];
const marcas      = Array.isArray(res.marcas) ? res.marcas : [];
const pantalla    = res.pantalla || null;

// Construir query optimizada para Google Shopping:
// Incluye tipo + marcas + must specs para encontrar productos específicos
const partes = [tipo];
if (marcas.length > 0) partes.push(marcas.slice(0,2).join(' '));
if (must.length > 0) partes.push(must.slice(0,2).join(' '));
if (keywords.length > 0 && !partes.some(p => keywords[0] && p.toLowerCase().includes(keywords[0].toLowerCase()))) {
  partes.push(keywords.slice(0,2).join(' '));
}
const q = partes.filter(Boolean).join(' ').trim();

return [{ json: { q, keywords, pMax: presupuesto, pMin, tipo, must, nice, marcas, pantalla, retryCount: 0 } }];

// ============================================================
// NORM PCCOMPONENTES - Calidad de Producto & Specs
// ============================================================
const STORE = 'PcComponentes';
const DOMAIN = 'pccomponentes.com';

let inputData = {};
try { inputData = $input.first().json || {}; } catch (e) { inputData = {}; }

let pCfg = {};
try { pCfg = $('Parsear Peticion').first().json || {}; } catch (e) {}
const must = Array.isArray(pCfg.must) ? pCfg.must : [];
const nice = Array.isArray(pCfg.nice) ? pCfg.nice : [];
const pMin = Number(pCfg.pMin) || 15;
const pMax = Number(pCfg.pMax) || 99999;
const tipo = String(pCfg.tipo || '').toLowerCase();

const noAccent = (s) => {
  if (!s) return '';
  return String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
};

const JUNK_WORDS = ['funda', 'maletin', 'mochila', 'seguro', 'garantia', 'montaje', 'instalacion', 'soporte', 'cable', 'adaptador', 'limpieza', 'reparacion', 'teclado para', 'bateria para', 'cargador'];

const extractPrices = (text) => {
  if (!text) return [];
  const out = [];
  const re = /(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?)\s*(?:€|euros|eur)/gi;
  let m;
  const str = String(text);
  while ((m = re.exec(str)) !== null) {
    let n = m[1].replace(/\./g, '').replace(',', '.');
    const v = parseFloat(n);
    if (!isNaN(v) && v > 5) out.push(v);
  }
  return out;
};

const scoreProduct = (title, snippet) => {
  const t = String(title || '');
  const s = String(snippet || '');
  const text = noAccent(t + ' ' + s);
  let score = 0;

  if (tipo && text.indexOf(tipo) !== -1) score += 50;

  for (var i = 0; i < JUNK_WORDS.length; i++) {
    if (noAccent(t).indexOf(JUNK_WORDS[i]) !== -1) { score -= 100; break; }
  }

  for (var i = 0; i < must.length; i++) {
    if (must[i] && text.indexOf(noAccent(must[i])) !== -1) score += 10;
  }
  for (var i = 0; i < nice.length; i++) {
    if (nice[i] && text.indexOf(noAccent(nice[i])) !== -1) score += 3;
  }
  return score;
};

const products = [];

const organic = inputData.organic_results;
if (organic && Array.isArray(organic)) {
  for (var i = 0; i < organic.length; i++) {
    const r = organic[i];
    if (!r || !r.link || !r.title) continue;

    let cleanLink = String(r.link).split('?')[0].split('#')[0];
    cleanLink = cleanLink.replace(/\/opiniones.*/i, '').replace(/\/caracteristicas.*/i, '');

    const link = cleanLink.toLowerCase();
    if (link.indexOf('/category/') !== -1 || link.indexOf('/c/') !== -1 || link.indexOf('/buscar') !== -1 || link.indexOf('/search') !== -1 || link.indexOf('query=') !== -1 || link.indexOf('/configurador') !== -1) continue;

    let price = 0;
    if (r.rich_snippet && r.rich_snippet.top && r.rich_snippet.top.detected_extensions && r.rich_snippet.top.detected_extensions.price) {
      price = Number(r.rich_snippet.top.detected_extensions.price);
    } else if (r.rich_snippet && r.rich_snippet.bottom && r.rich_snippet.bottom.detected_extensions && r.rich_snippet.bottom.detected_extensions.price) {
      price = Number(r.rich_snippet.bottom.detected_extensions.price);
    }
    if (!price) {
      const ps = extractPrices(String(r.title) + ' ' + String(r.snippet || ''));
      if (ps.length > 0) price = ps[0];
    }
    if (price <= 0) continue;

    products.push({
      source: STORE, title: String(r.title).trim(), price: price, link: cleanLink, snippet: r.snippet || '',
      score: scoreProduct(r.title, r.snippet || '')
    });
  }
}

const shopping = inputData.shopping_results;
if (shopping && Array.isArray(shopping)) {
  for (var i = 0; i < shopping.length; i++) {
    const r = shopping[i];
    if (!r || !r.link || !r.title) continue;
    const merchant = String(r.source || '').toLowerCase();
    if (merchant.indexOf('pccomponentes') === -1 && String(r.link).toLowerCase().indexOf(DOMAIN) === -1) continue;

    let cleanLink = String(r.link).split('?')[0].split('#')[0];
    cleanLink = cleanLink.replace(/\/opiniones.*/i, '').replace(/\/caracteristicas.*/i, '');

    const price = Number(r.extracted_price) || 0;
    if (price <= 0) continue;
    products.push({
      source: STORE, title: String(r.title).trim(), price: price, link: cleanLink, snippet: r.price || '',
      score: scoreProduct(r.title, r.title)
    });
  }
}

const seen = {};
const dedup = [];
for (var i = 0; i < products.length; i++) {
  const p = products[i];
  const key = String(p.link).toLowerCase();
  if (!seen[key]) {
    seen[key] = true;
    if (p.score < -20 || p.price > pMax + 100) continue; 
    dedup.push(p);
  }
}

dedup.sort((a, b) => {
  if (Math.abs(b.score - a.score) > 5) return b.score - a.score;
  const aValid = a.price >= pMin;
  const bValid = b.price >= pMin;
  if (aValid !== bValid) return aValid ? -1 : 1;
  return a.price - b.price;
});

return [{ json: { source: STORE, products: dedup, count: dedup.length } }];

