// Recibe items de los 4 normalizadores vía Merge Final
const allProducts = [];
const sourceStats = {};
$input.all().forEach(item => {
  const d    = item.json || {};
  const list = Array.isArray(d.products) ? d.products : [];
  const src  = d.source || 'Desconocido';
  sourceStats[src] = (sourceStats[src] || 0) + list.length;
  allProducts.push(...list);
});

let pCfg = {};
try { pCfg = $('Parsear Peticion').first().json || {}; } catch(e) {}
const pMin = Number(pCfg.pMin) || 0;
const pMax = Number(pCfg.pMax) || 99999;

// Deduplicar por URL base
const seen = new Set();
const dedup = [];
allProducts.forEach(p => {
  const key = String(p.link || '').split('?')[0].toLowerCase().trim();
  if (key && !seen.has(key) && Number(p.price) > 0 && p.title) {
    seen.add(key);
    dedup.push(p);
  }
});

// Separar por tienda
const byStore = {};
dedup.forEach(p => {
  if (!byStore[p.source]) byStore[p.source] = [];
  byStore[p.source].push(p);
});

// Ordenar por: score DESC → precio
const sortFn = (a, b) => {
  const scoreDiff = (b.score||0) - (a.score||0);
  if (Math.abs(scoreDiff) > 5) return scoreDiff;
  return a.price - b.price;
};

let finalProducts = [];
Object.keys(byStore).forEach(store => {
  byStore[store].sort(sortFn);
  // Coger los 3 mejores de cada tienda
  finalProducts.push(...byStore[store].slice(0, 3));
});

// Asegurar que no mandamos más de 12 al AI Agent
finalProducts = finalProducts.slice(0, 12);

return [{ json: { products: finalProducts, total: finalProducts.length, sourceStats, pCfg } }];

const agentOut = ($input.first().json.output || '').trim();
let pCfg = {};
try { pCfg = $('Parsear Peticion').first().json || {}; } catch(e) {}
let rawProducts = [];
try { rawProducts = $('Unificar Resultados').first().json.products || []; } catch(e) {}

let enriched = [];
try {
  const cleaned = agentOut.replace(/```json\s*/gi,'').replace(/```\s*/gi,'').trim();
  const s = cleaned.indexOf('['), e2 = cleaned.lastIndexOf(']');
  enriched = JSON.parse(s !== -1 && e2 > s ? cleaned.substring(s, e2+1) : cleaned);
  if (!Array.isArray(enriched)) enriched = [];
} catch(e) {
  // Fallback: usar productos crudos con campos vacíos para que el HTML use parseSpecs
  enriched = rawProducts.map(p => ({ ...p }));
}

// Garantizar que cada producto tiene todos los campos requeridos
const DEF = {
  MARCA:'', MODELO:'', PANTALLA:'', CPU:'',
  RAM:'', GPU:'', DISCO:'', SO:''
};
enriched = enriched.map(p => ({ ...DEF, ...p }));

return [{ json: { products: enriched, pCfg, total: enriched.length } }];

