const _inp     = $input.first().json;
const products = Array.isArray(_inp.products) ? _inp.products : [];
const params   = _inp.pCfg || {};

const STORES = ['Amazon','PcComponentes','Esprinet','DMI'];
const pMax   = Number(params.pMax) || 9999;
const pMin   = Number(params.pMin) || 0;
const tipo   = params.tipo  || 'Equipo';
const query  = params.q     || '';
const today  = new Date().toLocaleDateString('es-ES',{ day:'2-digit', month:'long', year:'numeric' });

const fmt = n => Number(n).toLocaleString('es-ES',{ minimumFractionDigits:2, maximumFractionDigits:2 }) + ' €';
const esc = s => String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');

// ── Extractor de specs como FALLBACK si el agente no rellenó ──
const parseSpecs = (title, snippet) => {
  const t = String(title||'') + ' ' + String(snippet||'');
  const tl = t.toLowerCase();

  let brand = '';
  const bl = ['ASUS','Lenovo','HP','Dell','MSI','Acer','Samsung','Apple','Medion','Gigabyte','Huawei','LG','Razer','Microsoft','Toshiba','Xiaomi','Honor'];
  for (const b of bl) { if (tl.includes(b.toLowerCase())) { brand = b; break; } }
  if (!brand) {
    if (tl.includes('thinkpad')||tl.includes('ideapad')||tl.includes('legion')) brand='Lenovo';
    else if (tl.includes('pavilion')||tl.includes('victus')||tl.includes('omen')) brand='HP';
    else if (tl.includes('vivobook')||tl.includes('zenbook')||tl.includes('rog')||tl.includes('tuf')) brand='ASUS';
    else if (tl.includes('inspiron')||tl.includes('latitude')||tl.includes('xps')) brand='Dell';
  }

  let screen = '';
  const scrM = t.match(/(\d{2}[.,]\d)\s*["'"″]/) || t.match(/(\d{2})\s*["'"″]/);
  if (scrM) screen = scrM[1].replace(',','.')+'"';
  else if (tl.includes('15.6')) screen='15.6"';
  else if (tl.includes('17.3')) screen='17.3"';
  else if (tl.includes('14"')||tl.includes('14 pul')) screen='14"';
  else if (tl.includes('13.3')||tl.includes('13"')) screen='13.3"';
  else if (tl.includes('27"')||tl.includes('27 pul')) screen='27"';
  else if (tl.includes('24"')||tl.includes('24 pul')) screen='24"';

  let cpu = '';
  const cpuM = t.match(/Core\s+i([3579])[\s-]*(\d{4,5}\w*)/i) || t.match(/Ryzen\s+([3579])\s+(\d{4}\w*)/i) || t.match(/\b(M[1234]\s*(?:Pro|Max|Ultra)?)\b/i);
  if (cpuM && cpuM[2]) { cpu = (tl.includes('ryzen') ? 'AMD Ryzen '+cpuM[1]+' ' : 'Intel Core i'+cpuM[1]+'-') + cpuM[2]; }
  else if (cpuM) cpu = cpuM[1];
  if (!cpu) {
    if (tl.includes('core ultra 5')) cpu='Intel Core Ultra 5';
    else if (tl.includes('core ultra 7')) cpu='Intel Core Ultra 7';
    else if (tl.includes('core i9')) cpu='Intel Core i9';
    else if (tl.includes('core i7')) cpu='Intel Core i7';
    else if (tl.includes('core i5')) cpu='Intel Core i5';
    else if (tl.includes('ryzen 9')) cpu='AMD Ryzen 9';
    else if (tl.includes('ryzen 7')) cpu='AMD Ryzen 7';
    else if (tl.includes('ryzen 5')) cpu='AMD Ryzen 5';
  }

  let ram = '';
  const ramM = t.match(/(\d{1,2})\s*GB\s*(?:RAM|DDR[45]|LPDDR)/i) || t.match(/(\d{1,2})\s*GB[\s/]/i);
  if (ramM) ram = ramM[1]+'GB';
  if (!ram) { if (tl.includes('32gb')) ram='32GB'; else if (tl.includes('16gb')) ram='16GB'; else if (tl.includes('8gb')) ram='8GB'; }

  let gpu = '';
  const gpuM = t.match(/(RTX)\s*(\d{4})\s*(Ti|Super)?/i) || t.match(/(GTX)\s*(\d{4})\s*(Ti)?/i) || t.match(/(RX)\s*(\d{4})/i);
  if (gpuM) gpu = gpuM[1].toUpperCase()+' '+gpuM[2]+(gpuM[3]?' '+gpuM[3]:'');
  if (!gpu) { if (tl.includes('rtx 4090')) gpu='RTX 4090'; else if (tl.includes('rtx 4080')) gpu='RTX 4080'; else if (tl.includes('rtx 4070')) gpu='RTX 4070'; else if (tl.includes('rtx 4060')) gpu='RTX 4060'; else if (tl.includes('rtx 4050')) gpu='RTX 4050'; else if (tl.includes('rtx 3060')) gpu='RTX 3060'; else if (tl.includes('rtx 3050')) gpu='RTX 3050'; else if (tl.includes('iris xe')) gpu='Intel Iris Xe'; else if (tl.includes('radeon 680')) gpu='AMD Radeon 680M'; else if (tl.includes('radeon')) gpu='AMD Radeon'; }

  let disk = '';
  const diskM = t.match(/(\d+)\s*TB\s*(?:SSD|NVMe)/i) || t.match(/(\d{3,4})\s*GB\s*(?:SSD|NVMe)/i) || t.match(/SSD\s*(?:de\s*)?(\d+)\s*(GB|TB)/i);
  if (diskM) disk = diskM[1]+(diskM[2]||'GB')+' SSD';
  if (!disk) { if (tl.includes('2tb')) disk='2TB'; else if (tl.includes('1tb ssd')) disk='1TB SSD'; else if (tl.includes('1tb')) disk='1TB HDD'; else if (tl.includes('512gb')) disk='512GB SSD'; else if (tl.includes('256gb')) disk='256GB SSD'; }

  let so = '';
  if (tl.includes('windows 11 home')) so='Windows 11 Home';
  else if (tl.includes('windows 11 pro')) so='Windows 11 Pro';
  else if (tl.includes('windows 11')) so='Windows 11';
  else if (tl.includes('sin sistema')||tl.includes('freedos')||tl.includes('free dos')||tl.includes('sin so')) so='Sin SO';
  else if (tl.includes('macos')||tl.includes('mac os')) so='macOS';
  else if (tl.includes('linux')) so='Linux';

  return { brand, screen, cpu, ram, gpu, disk, so };
};

// Usa dato del agente si es concreto, si no, el parseSpecs, si no 'Ver ficha'
const spec = (aiVal, fallback) => {
  if (aiVal && aiVal.trim() && aiVal !== 'Consultar' && aiVal !== 'Ver ficha técnica' && aiVal !== 'Ver ficha' && aiVal.length > 0) return aiVal;
  return fallback || 'Ver ficha';
};

// ── Agrupaciones ─────────────────────────────────────────────
// Top 3 global: ya vienen ordenados por proximidad al presupuesto
const inBudget = products.filter(p => Number(p.price) >= pMin && Number(p.price) <= pMax);
const top3     = inBudget.length >= 3 ? inBudget.slice(0,3) : products.slice(0,3);

// Top 3 por tienda
const byStore = {};
STORES.forEach(s => byStore[s] = []);
products.forEach(p => { if (byStore[p.source] && byStore[p.source].length < 3) byStore[p.source].push(p); });

const totalAnalyzed = products.length;
const activeStores  = STORES.filter(s => byStore[s].length > 0).length;
const bestMatchPrice= top3.length ? top3[0].price : 0;
const saving        = pMax - bestMatchPrice > 0 ? pMax - bestMatchPrice : 0;

// ── Renderizado de fila ───────────────────────────────────────
const TH = (label, cls='') => `<th class="th-sm ${cls}">${label}</th>`;
const SPEC_HEADERS = `
  ${TH('Marca')}${TH('Modelo')}${TH('Pantalla')}${TH('CPU','col-cpu')}
  ${TH('RAM')}${TH('GPU','col-gpu')}${TH('Disco')}${TH('SO')}`;

const row = (p, rank, rankCls) => {
  const sp = parseSpecs(p.title, p.snippet);
  const marca   = spec(p.MARCA,    sp.brand);
  const modelo  = spec(p.MODELO,   '');
  const screen  = spec(p.PANTALLA, sp.screen);
  const cpu     = spec(p.CPU,      sp.cpu);
  const ram     = spec(p.RAM,      sp.ram);
  const gpu     = spec(p.GPU,      sp.gpu);
  const disk    = spec(p.DISCO,    sp.disk);
  const so      = spec(p.SO,       sp.so);
  const overBdg = Number(p.price) > pMax;
  return `<tr>
    <td class="rank-cell"><span class="rank ${rankCls}">${rank}</span></td>
    <td class="spec-cell fw6">${esc(marca)}</td>
    <td class="spec-cell">${esc(modelo)||'<em class=\"dim\">—</em>'}</td>
    <td class="spec-cell">${esc(screen)}</td>
    <td class="spec-cell mono">${esc(cpu)}</td>
    <td class="spec-cell">${esc(ram)}</td>
    <td class="spec-cell mono">${esc(gpu)}</td>
    <td class="spec-cell">${esc(disk)}</td>
    <td class="spec-cell">${esc(so)}</td>
    <td class="store-cell"><span class="chip">${esc(p.source)}</span></td>
    <td class="price-cell">${fmt(Number(p.price))}${overBdg?'<span class=\"tag-warn\">+presup.</span>':''}</td>
    <td class="action-cell"><a class=\"btn-ver\" href=\"${esc(p.link)}\" target=\"_blank\">Ver oferta ↗</a></td>
  </tr>`;
};

