  '.btn-ver{display:inline-block;padding:4px 9px;background:var(--accent);color:#fff;text-decoration:none;border-radius:5px;font-size:8px;font-weight:600;border:1px solid var(--accent)}',
  '.dim{color:var(--muted);font-style:italic}',
  '.empty{text-align:center;color:var(--muted);font-style:italic;padding:16px}',
  '.section-sep{display:flex;align-items:center;gap:8px;margin:16px 0 10px;font-size:9.5px;font-weight:700;color:var(--ink);text-transform:uppercase;letter-spacing:.5px}',
  '.section-sep .bar{flex:1;height:1px;background:var(--line)}',
  '.ftr{display:flex;justify-content:space-between;font-size:8px;color:var(--muted);margin-top:14px;padding-top:10px;border-top:1px solid var(--line)}',
  '@page{size:A4 landscape;margin:8mm}',
  '@media print{.block,.stats,.hdr{page-break-inside:avoid}}'
].join('\n');

// ── HTML ─────────────────────────────────────────────────────
const FULL_TH = `<th class="th-rank">#</th>${SPEC_HEADERS}<th class="th-sm">Tienda</th><th style="text-align:right">Precio</th><th style="text-align:right">Enlace</th>`;

const renderTable = (items, rankCls) =>
  `<table class="tbl"><thead><tr>${FULL_TH}</tr></thead><tbody>${
    items.length
      ? items.map((p,i) => row(p, i+1, rankCls)).join('')
      : '<tr><td colspan="12" class="empty">Sin resultados en esta categoría.</td></tr>'
  }</tbody></table>`;

const top3Html = `
<div class="block hero">
  <div class="block-hd">
    <span class="badge-top3">⭐ TOP 3 GLOBAL</span>
    <div>
      <h2>Mejores opciones calidad/precio</h2>
      <div class="sub">Ordenados por proximidad al presupuesto de ${fmt(pMax)} · Categoría: ${esc(tipo)}</div>
    </div>
  </div>
  ${renderTable(top3, 'r1')}
</div>`;

const storeBlocks = STORES.map(store => {
  const items = byStore[store] || [];
  let logoHtml = `<span class="badge-store">${esc(store)}</span>`;
  if(store==='Amazon') logoHtml = `<img src="${LOGO_AMZ}" style="height:24px; width:auto; filter:brightness(0);">`;
  if(store==='PcComponentes') logoHtml = SVG_PCC.replace('<svg ', '<svg style="height:24px; width:auto;" ');
  if(store==='Esprinet') logoHtml = SVG_ESP.replace('<svg ', '<svg style="height:24px; width:auto;" ');
  if(store==='DMI') logoHtml = SVG_DMI.replace('<svg ', '<svg style="height:24px; width:auto;" ');

  return `
<div class="block">
  <div class="block-hd">
    <div style="margin-right:12px; display:flex; align-items:center;">${logoHtml}</div>
    <div>
      <h3 style="margin:0; padding:0; color:#1e293b;">Top 3 ${esc(store)}</h3>
      <div class="sub" style="margin:0; padding:0;">${items.length} producto(s) encontrado(s)</div>
    </div>
  </div>
  ${renderTable(items, 'r-store')}
</div>`;
}).join('');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="utf-8">
<title>Propuesta Hardware — ${esc(tipo)}</title>
<style>${css}</style>
</head>
<body><div class="page">

<header class="hdr">
  <div class="hdr-left">
    <div class="brand">
    <img class="brand-logo" src="data:image/png;base64,${LOGO_B64}" alt="Innovatek">
    <div class="brand-text">
      <div class="eyebrow">Informe Comparativo de Ofertas</div>
      <h1>Propuesta de Hardware · ${esc(tipo)}</h1>
    </div>

    </div>
  </div>
  <div class="distributors">
    <div class="dist-title">Distribuidores oficiales:</div>
    <div class="dist-logos">
      ${SVG_DMI}
      ${SVG_ESP}
      ${SVG_PCC}
      <img src="${LOGO_AMZ}" alt="Amazon">
    </div>
  </div>
  <div class="hdr-meta">
    <div class="meta-row"><span class="k">Fecha</span><span class="v">${today}</span></div>
    <div class="meta-row"><span class="k">Categoría</span><span class="v">${esc(tipo)}</span></div>
    <div class="meta-row"><span class="k">Presupuesto máx.</span><span class="v">${fmt(pMax)}</span></div>
    <div class="meta-row"><span class="k">Términos búsqueda</span><span class="v">${esc(query)}</span></div>
  </div>
</header>

<div class="stats">
  <div class="stat-card"><div class="stat-icon">📦</div><div><div class="stat-label">Productos analizados</div><div class="stat-value">${totalAnalyzed}</div></div></div>
  <div class="stat-card"><div class="stat-icon">🏪</div><div><div class="stat-label">Tiendas con resultados</div><div class="stat-value">${activeStores} / ${STORES.length}</div></div></div>
  <div class="stat-card"><div class="stat-icon">🎯</div><div><div class="stat-label">Mejor match precio</div><div class="stat-value">${bestMatchPrice ? fmt(bestMatchPrice) : '—'}</div></div></div>
  <div class="stat-card"><div class="stat-icon">💰</div><div><div class="stat-label">Margen vs presupuesto</div><div class="stat-value">${saving > 0 ? fmt(saving) : '—'}</div></div></div>
</div>

${top3Html}

<div class="section-sep"><span>Detalle por tienda · Top 3</span><div class="bar"></div></div>
${storeBlocks}

<footer class="ftr">
  <span>Generado automáticamente · n8n + Ollama qwen2.5:14b · Datos en tiempo real vía Rainforest API &amp; SerpApi</span>
  <span>${today}</span>
</footer>

</div></body></html>`;

return [{
  json: {
    total: products.length,
    top3Count: top3.length,
    activeStores,
    presupuesto: pMax
  },
  binary: {
    index: {
      data: Buffer.from(html, 'utf-8').toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
}];

let pCfg = {};
try { pCfg = $('Parsear Peticion').first().json || {}; } catch(e) {}
const q    = (pCfg.q || 'PC sobremesa') + ' calidad precio oferta';
const pMax = pCfg.pMax || 1000;
const pMin = Math.round((pCfg.pMin || 400) * 0.8); // ampliar rango en retry
return [{ json: { ...pCfg, q, pMin, retryCount: (pCfg.retryCount||0)+1 } }];
